from pathlib import Path
root = Path(__file__).parent
stats = {'ma':'Melee attack', 'md':'Melee defense', 'ra':'Ranged attack', 'rd':'Ranged defense', 'fit':'Fitness', 'int':'Intellect', 'cha':'Charisma', 'per':'Perception'}
def number(attr, label, value=0, extra=''):
    return f'<label>{label}<input type="number" name="attr_{attr}" value="{value}" {extra}></label>'
html = '''<div class="tfa-sheet">
<input type="hidden" name="attr_sheet_type" class="sheet-type" value="party">
<header><div class="eyebrow">TECHNO-FANTASY ADVENTURE · SECOND EDITION</div><h1>Beyond the known worlds</h1><p>A character dossier for strange lands and desperate battles.</p></header>
<section class="identity"><label>Name<input type="text" name="attr_character_name" placeholder="Character name"></label><label>Profile<select name="attr_sheet_type"><option value="party">Party Member</option><option value="foe">Foe</option></select></label><label>Role<select name="attr_role"><option>Champion</option><option selected>Fighter</option><option>Shooter</option><option>Specialist</option><option>Other</option></select></label></section>
<div class="party"><div class="mode-bar"><label>Play mode<select name="attr_play_mode"><option value="solo">Solo / Co-op / RPG</option><option value="pvp">PvP · opposed rolls</option></select></label><label>Type<select name="attr_character_type"><option>Major</option><option selected>Standard</option><option>Minor</option></select></label><label>Background<input type="text" name="attr_background" placeholder="Background / relevant stats"></label></div><p class="hint">Roll your attacks and defenses. Solo/co-op: meet the TN. PvP: enter the opposing roll; attack ties favor the defender.</p><h2>Stats <small>Final bonuses, including Role and permanent effects</small></h2><div class="stats">'''
for stat, label in stats.items():
    html += f'<div class="stat"><button type="action" name="act_{stat}">{stat.upper()}</button>{number(stat,label)}</div>'
html += '''</div></div><div class="foe"><div class="mode-bar"><label>Power level<select name="attr_power_level"><option value="4">4 · Major</option><option value="3" selected>3 · Standard</option><option value="2">2 · Minor</option><option value="1">1 · Minion</option></select></label><label>Behavior / morale<input type="text" name="attr_behavior" placeholder="Tactics, priorities, morale"></label></div><p class="hint">Game-controlled foe · no dice rolls. Players attack against MD/RD and defend against MA/RA. Use Party Member for every PvP model.</p><h2>Target numbers <small>Enter complete TNs, not stat bonuses</small></h2><div class="stats">'''
for stat,label in stats.items(): html += '<div class="stat"><strong>'+stat.upper()+' TN</strong>'+number('foe_'+stat,label,11,'min="0"')+'</div>'
html += '''</div></div><h2>Field condition</h2><div class="resources">'''
for attr,label,value in [('health','Health',15),('health_max','Max Health',15),('move','Move (inches)',5)]: html += number(attr,label,value,'min="0"')
html += '''<label>Passive PER<input type="number" name="attr_passive_per" value="11" readonly></label><label>Initiative chit<input type="text" name="attr_initiative" placeholder="Chit / activation"></label></div><p class="hint">At 0 Health: out of action. Type / power-level changes do not overwrite your Health or stats.</p><div class="conditions">'''
for attr,label in [('knocked_down','Knocked down'),('immobilized','Immobilized'),('poisoned','Poisoned'),('out_of_ammo','Out of ammo'),('shield_broken','Shield broken'),('field_off','Energy field offline')]: html += f'<label><input type="checkbox" name="attr_{attr}" value="1"> {label}</label>'
html += '\n</div><div class="party"><h2>Luck</h2><div class="resources">'+number('luck','Luck remaining',0,'min="0"')+'</div><p class="hint">Track starting Luck and spent points here. Only Party Members use Luck; this is separate from Boons.</p></div><h2>Weapons & protection</h2>'
for kind, title in [('melee','Melee weapons'),('ranged','Ranged weapons')]:
    html += f'<h3>{title}</h3><p class="hint">Add any number of weapons. Use Add to create an entry; Modify to delete or reorder entries.</p><fieldset class="repeating_{kind}weapons"><div class="weapon-entry"><label>Weapon<input type="text" name="attr_weapon_name" placeholder="Weapon name"></label>'+number('weapon_damage','Damage bonus',2)
    if kind == 'ranged': html += number('weapon_range','Range (inches)',12,'min="0"')
    else: html += number('weapon_reach','Reach (inches)',1,'min="0"')
    html += '<label class="full">Properties / notes<textarea name="attr_weapon_properties" placeholder="Special rules, ammunition, effects…"></textarea></label><button type="action" name="act_attack" class="weapon-roll">Attack with this weapon</button></div></fieldset>'
html += '''<div class="resources"><label>Armor / field<input type="text" name="attr_armor_name" placeholder="None / Light / Medium / Heavy / Energy Field"></label>'''+number('armor_dice','Armor dice',0,'min="0" max="12"')+'''<label>Shield<input type="checkbox" name="attr_shield" value="1"> Include +1 MD/RD in final stats or TNs</label></div><div class="party"><button type="action" name="act_armor" class="wide-button">Roll armor save</button><p class="hint">4–5: negate 1 damage; 6: negate 2. Damage and resources are applied manually. Armor saves belong to the player profile; use the table’s agreed procedure for GC armor.</p>'''+number('incoming_damage','Incoming damage bonus (weapon + attacker effects)',2)+'''<p class="hint">Defense damage includes negative Results and the entered incoming bonus, before armor. In PvP include any attacker Double Bonus or other damage effects in that bonus.</p></div><h2>Traits & abilities</h2><p class="hint">Use Add for a new trait; Modify to delete or reorder entries.</p><fieldset class="repeating_traits"><div class="entry"><label>Trait / ability<input type="text" name="attr_trait_name"></label><label>Uses remaining<input type="number" name="attr_trait_uses" min="0" value="0"></label><label class="full">Effects / Double Bonus / limitations<textarea name="attr_trait_notes"></textarea></label></div></fieldset><h2>Gear</h2><fieldset class="repeating_gear"><div class="entry"><label>Item<input type="text" name="attr_gear_name"></label><label>Uses<input type="number" name="attr_gear_uses" min="0" value="1"></label><label class="full">Notes<textarea name="attr_gear_notes"></textarea></label></div></fieldset><div class="party"><h2>Campaign record</h2><div class="resources">'''+number('boons','Boons',0,'min="0"')+number('bumps','Bumps',0,'min="0"')+'''<label>Warband<input type="text" name="attr_warband"></label></div><label>Advances, injuries & background notes<textarea name="attr_campaign_notes"></textarea></label><p class="hint">Boons: spend at most one per 3D6 check to reroll one die; accept the new die. Resolve rerolls in chat and recompute the result manually.</p></div><label>Notes<textarea name="attr_notes" placeholder="Description, tactics, reminders…"></textarea></label><footer>TFA 2E · Unofficial character sheet · Rules © Scott R. Pyle / Four-Color Studios</footer></div>
<rolltemplate class="sheet-rolltemplate-tfa"><div class="tfa-roll"><h3>{{name}}</h3><strong>{{action}}</strong>{{#armor}}<p>Armor dice: {{save0}} {{save1}} {{save2}} {{save3}} {{save4}} {{save5}} {{save6}} {{save7}} {{save8}} {{save9}} {{save10}} {{save11}}</p><p>Damage negated: {{computed::saved}}</p>{{#rollTotal() computed::short 1}}<p>If using an Energy Field: it shorts out after this attack.</p>{{/rollTotal() computed::short 1}}{{/armor}}{{^armor}}<p>Dice: {{d1}} {{d2}} {{d3}}</p><p>Stat {{bonus}} · modifier {{mod}}</p><p>Total <b>{{computed::total}}</b> vs <b>{{target}}</b></p><p>Results: {{computed::margin}}</p>{{#rollTotal() computed::success 1}}<p class="outcome">SUCCESS</p>{{/rollTotal() computed::success 1}}{{#rollTotal() computed::success 0}}<p class="outcome">FAILURE</p>{{/rollTotal() computed::success 0}}{{#rollTotal() attack 1}}<p>Damage before armor: {{computed::damage}}</p>{{/rollTotal() attack 1}}{{#rollTotal() defense 1}}{{#rollTotal() computed::success 0}}<p>Incoming damage before armor: {{computed::damage}}</p>{{/rollTotal() computed::success 0}}{{/rollTotal() defense 1}}{{#rollTotal() computed::db 1}}<p>Double Bonus rolled. Benefits require success; attack damage includes +2. On MD you may disengage 2″; on RD you may dive 2″ into nearby terrain. Check Traits for other effects.</p>{{/rollTotal() computed::db 1}}{{#rollTotal() computed::triples 1}}<p>Successful triples: +1 included.</p>{{/rollTotal() computed::triples 1}}{{#rollTotal() computed::ones 1}}<p>Double 1s: check ammunition, shield and opposing abilities.</p>{{/rollTotal() computed::ones 1}}{{#rollTotal() computed::twos 1}}<p>Double 2s: check special-weapon ammunition, shield and opposing abilities.</p>{{/rollTotal() computed::twos 1}}{{#rollTotal() computed::sixdef 1}}<p>Successful RD with double 6s: the GC attacker runs out of ammo.</p>{{/rollTotal() computed::sixdef 1}}{{/armor}}</div></rolltemplate>
'''
html += '<script type="text/worker">\n' + (root/'worker.js').read_text() + '\n</script>\n'
(root/'sheet.html').write_text(html)
